// CWE-79: an HTML escaper's output has no unescaped markup characters for the context it is used in.
import * as fc from 'fast-check';
import { show } from './cwe.ts';
import { securityLaw } from './law.ts';
import type { SecurityLaw } from './law.ts';

/** A hostile string for a law parameter: `law safe(s: HtmlPayload) => escaping.holds(s)`. Generated by `htmlPayloads`. */
export type HtmlPayload = string & { readonly __tslawsHtml: true };

export const htmlCorpus: readonly string[] = [
  '<script>alert(1)</script>',
  '<img src=x onerror=alert(1)>',
  '"><svg/onload=alert(1)>',
  "'><script>alert(1)</script>",
  "' onmouseover='alert(1)",
  '" onfocus="alert(1)" autofocus="',
  '`onmouseover=alert(1)',
  '<a href="javascript:alert(1)">x</a>',
  '</textarea><script>alert(1)</script>',
  '<<script>script>',
  '&lt;script&gt;',
  '&#60;script&#62;',
  '<',
  '"',
  "'",
  '`',
  '<<<<>>>>""""\'\'\'\'````',
];

const pieces = [
  '<',
  '>',
  '"',
  "'",
  '`',
  '&',
  '=',
  ' ',
  '/',
  'script',
  'img',
  'onerror',
  'alert(1)',
  'javascript:',
  '&lt;',
  '&#x3c;',
  ' ',
  '\0',
  'a',
];

/**
 * Strings heavy in the characters an escaper must handle, many of them repeated (an escaper that replaces only the
 * first one fails on them).
 */
export function htmlPayloads(): fc.Arbitrary<HtmlPayload> {
  return fc
    .oneof(
      {
        weight: 6,
        arbitrary: fc.array(fc.constantFrom(...pieces), { minLength: 1, maxLength: 24 }).map((p) => p.join('')),
      },
      { weight: 2, arbitrary: fc.constantFrom(...htmlCorpus) },
      { weight: 1, arbitrary: fc.string() },
    )
    .map((s) => s as HtmlPayload);
}

export interface HtmlEscapeOptions {
  /**
   * Where the output goes. `html` is element text: no `<`. `attribute` (the default) is a quoted attribute value: no
   * `<`, `"`, `'` or backtick. `unquoted-attribute` also forbids whitespace, `=` and `>`.
   */
  context?: 'html' | 'attribute' | 'unquoted-attribute';
}

const forbidden = {
  html: '<',
  attribute: '<"\'`',
  'unquoted-attribute': '<>"\'` \t\n\r\f=',
} as const;

/** CWE-79. `escape(input)` must return a string without any character `context` forbids. A throw refuses the input. */
export function htmlEscaping(
  escape: (input: string) => unknown,
  options: HtmlEscapeOptions = {},
): SecurityLaw<HtmlPayload> {
  const context = options.context ?? 'attribute';
  const chars = forbidden[context];
  return securityLaw<HtmlPayload>({
    id: 'html-escaping',
    cwe: ['CWE-79'],
    title: `an HTML escaper leaves no unescaped markup characters in ${context} context`,
    input: htmlPayloads(),
    corpus: htmlCorpus as readonly HtmlPayload[],
    verdict: (input) => {
      let out: unknown;
      try {
        out = escape(input);
      } catch {
        return undefined;
      }
      if (typeof out !== 'string') return { detail: `escape(${show(input)}) returned ${show(out)}, not a string` };
      for (const ch of out)
        if (chars.includes(ch))
          return {
            detail: `escape(${show(input)}) returned ${show(out)}, with an unescaped ${show(ch)} for ${context} context`,
          };
      return undefined;
    },
  });
}
